import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Alibaba Cloud Model Studio map","description":"Model Studio is the API and app platform, not the chat app and not the IDE. Decide API vs plan vs console first.","frontmatter":{"title":"Alibaba Cloud Model Studio map","description":"Model Studio is the API and app platform, not the chat app and not the IDE. Decide API vs plan vs console first.","domain":"product","tags":["model-platform"],"role":"map"},"headers":[],"relativePath":"products/bailian/index.md","filePath":"products/bailian/index.md","lastUpdated":1787110548000}'),s={name:"products/bailian/index.md"};function l(i,a,d,r,p,h){return o(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="alibaba-cloud-model-studio-map" tabindex="-1">Alibaba Cloud Model Studio map <a class="header-anchor" href="#alibaba-cloud-model-studio-map" aria-label="Permalink to &quot;Alibaba Cloud Model Studio map&quot;">​</a></h1><blockquote><p><strong>Alibaba Cloud Model Studio</strong> (百炼) is a one-stop model and application platform: developers call OpenAI-compatible APIs; operators build agents and knowledge-base Q&amp;A in the console. <a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">Product introduction</a></p><p>This page only answers &quot;what am I doing → which slice of Model Studio&quot;. Operations live in the <a href="./bailian.html">tutorial</a>. Tables live in the <a href="./bailian-cheatsheet.html">cheatsheet</a>. Name collisions live in the <a href="./bailian-glossary.html">glossary</a>.</p><p>Model internals are out of scope. See <a href="/tech/fundamentals/LLM.html">LLM fundamentals</a> and <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</p></blockquote><h2 id="product-map" tabindex="-1">Product map <a class="header-anchor" href="#product-map" aria-label="Permalink to &quot;Product map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alibaba Cloud AI (this directory documents Model Studio only)</span></span>
<span class="line"><span>├── Model Studio (this set)</span></span>
<span class="line"><span>│   ├── Console / playground</span></span>
<span class="line"><span>│   ├── Model APIs (OpenAI-compatible / Anthropic-compatible / DashScope)</span></span>
<span class="line"><span>│   ├── Token Plan / Coding Plan</span></span>
<span class="line"><span>│   ├── Agents / workflows / knowledge base / MCP</span></span>
<span class="line"><span>│   ├── Model Studio CLI (\`bl\` / \`bailian\`)</span></span>
<span class="line"><span>│   └── Fine-tune / deploy / evaluate (one line, no how-to)</span></span>
<span class="line"><span>├── Qwen chat — separate product, issue #83, no tutorial here</span></span>
<span class="line"><span>├── Tongyi Lingma / Qoder CN (formerly Lingma) — IDE, issue #84, no tutorial here</span></span>
<span class="line"><span>└── Not this site: ECS / OSS / PAI / DashVector / GBI / Quanmiao</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Official first-level entry</th><th>This site</th></tr></thead><tbody><tr><td>Product intro, first API call, playground</td><td><a href="./bailian.html">Tutorial</a></td></tr><tr><td>Model list, billing, Token Plan, Coding Plan, regions</td><td><a href="./bailian-cheatsheet.html">Cheatsheet</a></td></tr><tr><td>Clients / tools, free-quota stop, CLI, no-code Q&amp;A</td><td><a href="./bailian-cookbook.html">Cookbook</a></td></tr><tr><td>Agent 1.0 / 2.0, workspace, three protocols, two plans</td><td><a href="./bailian-glossary.html">Glossary</a></td></tr><tr><td>Fine-tune / deploy / evaluate</td><td>Official docs only</td></tr><tr><td>Qwen chat</td><td>One line → #83</td></tr><tr><td>Qoder CN (formerly Lingma)</td><td>One line → #84</td></tr><tr><td>ECS / OSS / PAI / GBI / Quanmiao</td><td><strong>Not this site</strong></td></tr></tbody></table><h3 id="quick-decision" tabindex="-1">Quick decision <a class="header-anchor" href="#quick-decision" aria-label="Permalink to &quot;Quick decision&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What am I trying to do?</span></span>
<span class="line"><span>├── Call Qwen or a third-party model from my front end / Node service</span></span>
<span class="line"><span>│   └── → Model Studio API (OpenAI-compatible) → [tutorial](./bailian)</span></span>
<span class="line"><span>├── Feed Alibaba Cloud quota into Claude Code / Cursor / Chatbox</span></span>
<span class="line"><span>│   └── → Token Plan (what the official overview recommends for new buys) or Coding Plan</span></span>
<span class="line"><span>│       └── Key and base URL must be a pair → [Cookbook](./bailian-cookbook)</span></span>
<span class="line"><span>├── No code, a knowledge-base Q&amp;A or agent</span></span>
<span class="line"><span>│   └── → Console apps (prefer Agent 2.0)</span></span>
<span class="line"><span>├── Let a local agent drive image / video / speech tools</span></span>
<span class="line"><span>│   └── → Model Studio CLI (\`bl\`)</span></span>
<span class="line"><span>├── Just chat with Tongyi, no API</span></span>
<span class="line"><span>│   └── → Qwen (#83), not Model Studio</span></span>
<span class="line"><span>├── An Alibaba-branded coding IDE</span></span>
<span class="line"><span>│   └── → Qoder CN / Lingma (#84), not Model Studio</span></span>
<span class="line"><span>└── A VM or object storage</span></span>
<span class="line"><span>    └── → Not this site. No ECS / OSS handbook here</span></span></code></pre></div><p>Three expensive mix-ups:</p><table tabindex="0"><thead><tr><th>Easy to confuse</th><th>Difference</th></tr></thead><tbody><tr><td><strong>Model Studio</strong> vs <strong>Qwen</strong></td><td>Studio is the platform. Qwen is a model family and a separate chat product. <a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></td></tr><tr><td><strong>Model Studio</strong> vs <strong>Lingma / Qoder CN</strong></td><td>Qoder CN is the IDE. It can <em>consume</em> a Studio key. It is not Studio. <a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">Official page</a></td></tr><tr><td><strong>Pay-as-you-go key</strong> vs <strong>plan key</strong></td><td>PAYG is <code>sk-</code> / <code>sk-ws</code>. Coding Plan / Token Plan dedicated keys are <code>sk-sp-</code>. A mismatched host either returns <code>invalid_api_key</code> or <strong>bills PAYG</strong>. <a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a></td></tr></tbody></table><h2 id="which-page" tabindex="-1">Which page <a class="header-anchor" href="#which-page" aria-label="Permalink to &quot;Which page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Type</th><th>When</th></tr></thead><tbody><tr><td><a href="./bailian.html">Tutorial</a></td><td>Tutorial</td><td>First time: activate → key → first Node call</td></tr><tr><td><a href="./bailian-cookbook.html">Cookbook</a></td><td>How-to</td><td>You can already call; you have a concrete problem</td></tr><tr><td><a href="./bailian-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>Regions, URLs, plan table, official links</td></tr><tr><td><a href="./bailian-glossary.html">Glossary</a></td><td>Explanation</td><td>Two names collided, or two official pages disagree</td></tr></tbody></table><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><ol><li>Use the tree above. Confirm you want the platform, not Qwen chat or Lingma.</li><li>Walk the <a href="./bailian.html">tutorial</a>: primary account, key, env var, one <code>qwen-plus</code> call.</li><li>Product integration → <a href="./bailian-cookbook.html">Cookbook · OpenAI-compatible</a>. Coding tools → <a href="./bailian-cookbook.html">Cookbook · do not mix keys</a>.</li><li>Look up IDs only on the <a href="./bailian-cheatsheet.html">cheatsheet</a> and the official model list. Do not pin a full model table in notes.</li></ol><h2 id="official-links" tabindex="-1">Official links <a class="header-anchor" href="#official-links" aria-label="Permalink to &quot;Official links&quot;">​</a></h2><ul><li><a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">China product page</a></li><li><a href="https://www.alibabacloud.com/help/en/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">What is Model Studio (EN)</a></li><li><a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">What is Model Studio (ZH)</a></li><li><a href="https://www.alibabacloud.com/help/en/model-studio/models" target="_blank" rel="noreferrer">Models</a></li><li><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">Console</a></li></ul>`,15)])])}const g=e(s,[["render",l]]);export{f as __pageData,g as default};
